import{_ as s,o as t,c as e,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"スキル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guides/skills.md","filePath":"ja/guides/skills.md","lastUpdated":1792323081000}'),l={name:"ja/guides/skills.md"};function d(n,a,o,r,p,c){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="スキル" tabindex="-1">スキル <a class="header-anchor" href="#スキル" aria-label="Permalink to &quot;スキル&quot;">​</a></h1><p>**スキル（Skill）**は再利用可能なプロンプトモジュールで、口調・手順・ツールの使い方といった決まったやり方を Bot に教えるためのものです。スキルに専用の管理画面はありません——ワークスペース内のファイルそのものであり、正しいディレクトリに置くだけで読み込まれます。</p><div class="tip custom-block"><p class="custom-block-title">制限</p><p>1 つのセッションで同時にリクエストできるスキルは最大 5 件です。注入されるサイズは 1 スキルあたり最大 64 KiB、合計で最大 256 KiB です。これらの上限は変更できません。</p></div><h2 id="スキルの形" tabindex="-1">スキルの形 <a class="header-anchor" href="#スキルの形" aria-label="Permalink to &quot;スキルの形&quot;">​</a></h2><p>スキルは 1 つのディレクトリで、その中に YAML ヘッダー付きの <code>SKILL.md</code> を置きます。最低限、安定した <code>name</code> と短い <code>description</code> が必要です。本文が、実際に Agent へ注入される説明になります。</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coder-skill</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Enables advanced coding workflows and tool usage.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Coder Skill</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">コードは明快に書き、トレードオフを説明し、必要なときはファイル／コマンドツールを使ってください。</span></span></code></pre></div><p>名前はシンプルな ASCII にし（例: <code>coder-skill</code>、<code>research</code>）、スペースは入れないでください——名前はそのままディレクトリ名にもなります。</p><h2 id="どのディレクトリに置くか" tabindex="-1">どのディレクトリに置くか <a class="header-anchor" href="#どのディレクトリに置くか" aria-label="Permalink to &quot;どのディレクトリに置くか&quot;">​</a></h2><p>自分で書いたスキルは、Bot のワークスペースの次のディレクトリに置きます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/skills/user/personal/&lt;スキル名&gt;/SKILL.md</span></span></code></pre></div><p>置き方は自由です。Bot の <strong>ファイル</strong> タブで直接ディレクトリとファイルを作成しても、<strong>Terminal</strong> で操作しても、あるいは Bot 自身に作らせても構いません——ワークスペースには <code>skill-creator</code> スキルが最初から入っているので、ほしい手順をきちんと説明すれば、正しい場所にファイルを書いてくれます。</p><p>ほかのディレクトリも目にしますが、<strong>手動でファイルを置いてはいけません</strong>。</p><table tabindex="0"><thead><tr><th>ディレクトリ</th><th>所有者</th></tr></thead><tbody><tr><td><code>/data/skills/user/personal/</code></td><td><strong>あなた</strong>。手書きのスキルはすべてここに置きます</td></tr><tr><td><code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code></td><td><a href="./supermarket.html">アプリ</a>。App のインストール・更新・アンインストールと一緒に処理されるため、手で変更しないでください</td></tr><tr><td><code>/data/.memoh/skills/</code></td><td>ワークスペーステンプレートの内蔵スキル（<code>skill-creator</code> など）。ワークスペースを初期化するたびにテンプレート版へ戻されるため、編集しても上書きされます。カスタマイズしたい場合は別の名前で自分のディレクトリへコピーしてください</td></tr><tr><td><code>/data/.skills/</code>、<code>/data/.agents/skills/</code></td><td>旧版向けの互換パス。検出専用で、新規追加はしないでください</td></tr></tbody></table><h2 id="同名のスキルがある場合" tabindex="-1">同名のスキルがある場合 <a class="header-anchor" href="#同名のスキルがある場合" aria-label="Permalink to &quot;同名のスキルがある場合&quot;">​</a></h2><p><strong>スキル名がそのまま識別子です</strong>。同名のスキルがいくつのディレクトリにあっても、同時に有効になるのは 1 つだけです。自分のディレクトリにある同名スキルは、旧版互換パスにあるものより優先されます。ある App のスキルの挙動を変えたいときは、そのファイルを編集するのではなく、新しい名前で自分のバージョンを書いてください。</p><h2 id="おすすめ" tabindex="-1">おすすめ <a class="header-anchor" href="#おすすめ" aria-label="Permalink to &quot;おすすめ&quot;">​</a></h2><ol><li>まずは少数精鋭にし、<code>name</code> と <code>description</code> を明確に書きます——Agent は説明を見て、そのスキルを読み込むかどうかを決めます。</li><li>繰り返し登場する手順だけをスキルとして固定する価値があります。一回限りの要望はその場で伝えれば十分です。</li><li>再利用できるものは<a href="./supermarket.html">マーケットプレイス</a>からインストールし、コピーの複製を増やさないようにします。</li></ol>`,17)])])}const g=s(l,[["render",d]]);export{k as __pageData,g as default};
